describe('Table Row Filtering by Search Input', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should filter table rows when user types in search input', () => {
    // Verify table is visible and contains initial rows
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify initial rows contain expected data
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');
    cy.get('[data-testid="table-row"]').eq(1).should('contain', 'Jane Smith');

    // Type search term into the input field
    cy.get('[data-testid="search-input"]').type('John');

    // Wait for API call and table update
    cy.wait('@filterTableRequest');

    // Verify only matching rows are displayed
    cy.get('[data-testid="table-row"]').should('have.length', 1);

    // Verify the visible row contains the search term
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');

    // Verify other rows are hidden
    cy.get('[data-testid="table-row"]').eq(1).should('not.exist');

    // Verify search input retains the typed value
    cy.get('[data-testid="search-input"]').should('have.value', 'John');
  });

  it('should handle empty search input and display all rows', () => {
    // Verify table is visible and contains initial rows
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Type a search term and verify filtering occurs
    cy.get('[data-testid="search-input"]').type('Jane');
    cy.wait('@filterTableRequest');
    cy.get('[data-testid="table-row"]').should('have.length', 1);

    // Clear the search input
    cy.get('[data-testid="search-input"]').clear();

    // Wait for API call to reset filter
    cy.wait('@filterTableRequest');

    // Verify all rows are displayed again
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 1);

    // Verify the search input is empty
    cy.get('[data-testid="search-input"]').should('have.value', '');

    // Verify all original rows are visible
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');
    cy.get('[data-testid="table-row"]').eq(1).should('contain', 'Jane Smith');
  });
});
